    let mut s: i32 = started;
    let mut j: i32 = 0;
    if ((kind == 1) || ((kind == 2) || ((kind == 6) || ((kind == 8) || (kind == 9))))) && (crate::port::cells_at(c, p) == dflt) {
        return started;
    }
    if kind == 1 {
        s = pl_begin(t, pr, 2, s, key);
        crate::port::text_i32(t, crate::port::cells_at(c, p));
        return s;
    }
    if kind == 2 {
        s = pl_begin(t, pr, 2, s, key);
        js_cpt(t, crate::port::cells_at(c, p));
        return s;
    }
    if kind == 3 {
        s = pl_begin(t, pr, 2, s, key);
        pl_quad(t, pr, c, p);
        return s;
    }
    if kind == 4 {
        if (crate::port::cells_at(c, p) == dflt) && (crate::port::cells_at(c, p + 1) == arg) {
            return started;
        }
        s = pl_begin(t, pr, 2, s, key);
        crate::port::text_ascii(t, "[");
        crate::port::text_i32(t, crate::port::cells_at(c, p));
        js_fsep(t, pr, 1);
        crate::port::text_i32(t, crate::port::cells_at(c, p + 1));
        crate::port::text_ascii(t, "]");
        return s;
    }
    if kind == 5 {
        if crate::port::cells_at(c, p + 1) == dflt {
            return started;
        }
        s = pl_begin(t, pr, 2, s, key);
        crate::port::text_ascii(t, "[\"");
        ea_emit_name(t, crate::port::cells_at(c, p));
        crate::port::text_ascii(t, "\",");
        if pr == 1 {
            crate::port::text_ascii(t, " ");
        }
        crate::port::text_i32(t, crate::port::cells_at(c, p + 1));
        crate::port::text_ascii(t, "]");
        return s;
    }
    if (kind == 6) || ((kind == 8) || (kind == 9)) {
        s = pl_begin(t, pr, 2, s, key);
        crate::port::text_ascii(t, "\"");
        if kind == 6 {
            dr_emit_name(t, crate::port::cells_at(c, p));
        }
        if kind == 8 {
            plh_emit_name(t, crate::port::cells_at(c, p));
        }
        if kind == 9 {
            pls_emit_name(t, crate::port::cells_at(c, p));
        }
        crate::port::text_ascii(t, "\"");
        return s;
    }
    if kind == 7 {
        s = pl_begin(t, pr, 2, s, key);
        crate::port::text_ascii(t, "[");
        while j < arg {
            js_fsep(t, pr, j);
            crate::port::text_i32(t, crate::port::cells_at(c, p + j));
            j += 1;
        }
        crate::port::text_ascii(t, "]");
        return s;
    }
